import hashlib, struct

def bincode_basic(q,a,tag=True,strlen='u64',endian='<',tagtype='u32'):
    out=b''
    if tag:
        if tagtype=='u32': out+=struct.pack(endian+'I',0)
        elif tagtype=='u8': out+=struct.pack('B',0)
        elif tagtype=='u64': out+=struct.pack(endian+'Q',0)
    if strlen=='u64': fmt=endian+'Q'
    elif strlen=='u32': fmt=endian+'I'
    elif strlen=='u8': fmt='B'
    for s in (q,a):
        out+=struct.pack(fmt,len(s.encode()))+s.encode()
    return out
